import json
grid = [[0]*30 for _ in range(30)]
cycle = {1:2, 2:5, 3:0, 0:5}
for i in range(1,26):
    for j in range(1,26):
        if i in (1,25) or j in (1,25): grid[i][j] = 5
for k in range(1,12):
    c = cycle[k % 4]
    lo, hi = 1+k, 25-k
    for t in range(lo, hi+1):
        grid[lo][t] = c; grid[hi][t] = c; grid[t][lo] = c; grid[t][hi] = c
assert all(len(r) == 30 for r in grid) and len(grid) == 30
print(json.dumps({"action": "submit", "grid": grid}, separators=(',', ':')))

# diff the two independently built grids and sanity-check ring structure
diffs = [(i,j,g[i][j],grid[i][j]) for i in range(30) for j in range(30) if g[i][j] != grid[i][j]]
print("diffs:", diffs[:10], "count", len(diffs))
# verify ring colors explicitly by depth
ok = True
for i in range(30):
    for j in range(30):
        if 1<=i<=25 and 1<=j<=25:
            if i in(1,25) or j in(1,25):
                exp = 5
            else:
                d = min(i-1, 25-i, j-1, 25-j)
                exp = cycle[d % 4] if d <= 11 else 0
            if grid[i][j] != exp:
                ok = False; print("bad", i, j, grid[i][j], exp)
print("structure ok:", ok)

